use crate::menu::*;
use crate::engine::Btn;
fn context() -> Context { Context { workspace: "ws-1".into(), tab: "tab-1".into(), pane: "pane-1".into(), workspace_label: "Project".into(), pane_label: "Shell".into(), cwd: Some("/tmp/project".into()) } }
fn settings() -> SettingsSnapshot { SettingsSnapshot { labels: LabelStyle::Both, voice_button: Btn::RStick, max_seconds: 47, model: "/models/base.bin".into(), language: "en".into(), config_path: "/config.toml".into(), version: "v1".into() } }
fn menu() -> Menu { Menu::new(7, Some(context()), settings(), "Space 123".into(), "gamepad/123".into()) }
fn press(m: &mut Menu, input: Input) -> Vec<Effect> { m.input(input, m.revision()) }
fn select(m: &mut Menu, index: usize) { for _ in 0..30 { press(m, Input::Up); } for _ in 0..index { press(m, Input::Down); } }
fn enter(m: &mut Menu, index: usize) -> Vec<Effect> { select(m,index); press(m,Input::Activate) }
fn read(e: Vec<Effect>) -> ReadRequest { match e.into_iter().next().unwrap() { Effect::Read(r)=>r, other=>panic!("{other:?}") } }
fn operation(e: Vec<Effect>) -> Operation { match e.into_iter().next().unwrap() { Effect::Mutate(r)=>r, other=>panic!("{other:?}") } }
fn repository() -> Repository { Repository { name: "project".into(), root: "/tmp/project".into(), source_checkout: "/tmp/project".into(), base_commit: "abc123".into(), entries: vec![Worktree { path:"/tmp/project".into(), branch:Some("main".into()), workspace:Some("ws-1".into()), primary:true, bare:false }, Worktree { path:"/tmp/linked".into(), branch:Some("feature".into()), workspace:Some("ws-2".into()), primary:false,bare:false }, Worktree {path:"/tmp/closed".into(),branch:None,workspace:None,primary:false,bare:false}, Worktree {path:"/tmp/bare".into(),branch:None,workspace:Some("ws-3".into()),primary:false,bare:true}] } }
fn load_repo(m:&mut Menu) { let r=read(enter(m,1)); assert!(m.receive(Response::Read { id:r.id, result:Ok(ReadData::Repository(repository())) })); }
#[test] fn root_navigation_and_scope() { let mut m=menu(); assert_eq!(m.view().rows.iter().map(|r| r.label.as_str()).collect::<Vec<_>>(),vec!["New space","Worktrees","Pane actions","Close…","Settings","Logs","Controls"]); select(&mut m,99); assert_eq!(m.view().selected,6); press(&mut m,Input::Right); assert_eq!(m.view().breadcrumb,"Main / Controls"); press(&mut m,Input::Back); assert_eq!(m.view().selected,6); press(&mut m,Input::Left); assert!(!m.is_open()); }
#[test] fn optional_scope_and_changed_identity() { let mut m=Menu::new(1,None,settings(),"Space".into(),"branch".into()); assert!(m.view().rows[0].disabled.is_some()); enter(&mut m,4); assert_eq!(m.view().scope,"Global"); assert!(m.observe_context(Ok(Some(context())))); assert!(!m.is_open()); let mut m=menu(); let mut c=context(); c.pane="different".into(); assert!(m.observe_context(Ok(Some(c)))); assert!(!m.is_open()); let mut m=menu(); assert!(m.observe_context(Err("snapshot failed".into()))); assert!(!m.is_open()); }
#[test] fn ack_and_right_never_execute_leaf() { let mut m=menu(); enter(&mut m,2); let rev=m.revision(); press(&mut m,Input::Down); assert!(m.revision()>rev); assert!(m.input(Input::Activate,rev).is_empty()); assert_eq!(m.view().breadcrumb,"Main / Pane actions"); assert!(press(&mut m,Input::Right).is_empty()); assert!(m.pending().is_none()); let op=operation(press(&mut m,Input::Activate)); assert_eq!(op.command,Command::Split { direction:SplitDirection::Down,cwd:"/tmp/project".into() }); assert_eq!(op.context,Some(context())); assert!(press(&mut m,Input::Activate).is_empty()); }
#[test] fn close_cancel_then_exact_once() { let mut m=menu(); enter(&mut m,3); enter(&mut m,0); assert_eq!(m.view().selected,0); assert!(m.view().details.join(" ").contains("pane-1")); assert!(press(&mut m,Input::Activate).is_empty()); assert_eq!(m.view().breadcrumb,"Main / Close…"); enter(&mut m,1); press(&mut m,Input::Down); let op=operation(press(&mut m,Input::Activate)); assert_eq!(op.command,Command::CloseWorkspace); assert!(press(&mut m,Input::Activate).is_empty()); assert!(m.pending().is_some()); }
#[test] fn reads_discard_after_back_and_wrong_identity() { let mut m=menu(); let r=read(enter(&mut m,1)); assert!(m.view().status.contains("Loading")); press(&mut m,Input::Back); assert!(!m.receive(Response::Read {id:r.id,result:Ok(ReadData::Repository(repository()))})); assert_eq!(m.view().breadcrumb,"Main"); let r=read(enter(&mut m,1)); let wrong=RequestId {session:99,serial:r.id.serial}; assert!(!m.receive(Response::Read{id:wrong,result:Ok(ReadData::Repository(repository()))})); assert!(m.receive(Response::Read{id:r.id,result:Ok(ReadData::Repository(repository()))})); assert!(m.view().details.join(" ").contains("/tmp/project")); }
#[test] fn worktree_commands_use_paths_and_pinned_base() { let mut m=menu(); load_repo(&mut m); enter(&mut m,0); let op=operation(enter(&mut m,1)); assert_eq!(op.command,Command::CreateWorktree { branch:"gamepad/123".into(),base:"abc123".into(),repository:"/tmp/project".into() }); let mut m=menu(); load_repo(&mut m); enter(&mut m,1); let op=operation(enter(&mut m,1)); assert_eq!(op.command,Command::OpenWorktree {path:"/tmp/linked".into(),workspace:Some("ws-2".into())}); let mut m=menu(); load_repo(&mut m); enter(&mut m,2); assert!(m.view().rows[0].disabled.is_some()); assert!(m.view().rows[2].disabled.is_some()); assert!(m.view().rows[3].disabled.is_some()); enter(&mut m,1); assert_eq!(m.view().selected,0); assert!(m.view().details.join(" ").contains("/tmp/linked")); let op=operation(enter(&mut m,1)); assert_eq!(op.command,Command::RemoveWorktree {path:"/tmp/linked".into(),workspace:"ws-2".into()}); }
#[test] fn empty_repository_and_read_failure_are_actionable() { let mut m=menu(); let r=read(enter(&mut m,1)); assert!(m.receive(Response::Read{id:r.id,result:Err("No repository".into())})); assert!(m.view().status.contains("No repository")); assert!(m.view().rows.iter().all(|r|r.disabled.is_some())); let mut m=menu(); let r=read(enter(&mut m,1)); let mut repo=repository();repo.entries.clear(); assert!(m.receive(Response::Read{id:r.id,result:Ok(ReadData::Repository(repo))})); enter(&mut m,1); assert_eq!(m.view().rows[0].label,"No worktrees"); assert!(m.view().rows[0].disabled.is_some()); }
#[test] fn text_grid_edits_unicode_cancels_and_validates() { let mut e=TextEditor::new(Field::Label,"猫é".into()); e.input(Input::Delete); assert_eq!(e.buffer,"猫"); e.input(Input::Activate); assert_eq!(e.buffer,"猫a"); e.input(Input::Page); e.input(Input::Activate); assert_eq!(e.buffer,"猫aA"); e.input(Input::Page); assert!(e.cells().contains(&"/".to_string())); assert!(e.cells().contains(&"_".to_string())); assert!(e.cells().contains(&"-".to_string())); assert_eq!(e.input(Input::Back),EditResult::Cancelled); assert!(validate(Field::Name,"").is_err()); assert!(validate(Field::Name,&"a".repeat(81)).is_err()); assert!(validate(Field::Branch,&"a".repeat(201)).is_err()); assert!(validate(Field::Label,"bad\x1b").is_err()); assert!(validate(Field::Branch,"feature/good-name_123").is_ok()); }
#[test] fn editing_forms_and_cwd_validation() { let mut m=menu();enter(&mut m,0);enter(&mut m,0);press(&mut m,Input::Delete);press(&mut m,Input::Back);assert!(m.view().rows[0].label.contains("Space 123"));let op=operation(enter(&mut m,1));assert_eq!(op.command,Command::CreateSpace {name:"Space 123".into(),cwd:"/tmp/project".into()}); let mut c=context(); c.cwd=Some("relative".into());let m=Menu::new(1,Some(c),settings(),"Space".into(),"b".into());assert!(m.view().rows[0].disabled.is_some()); }
#[test] fn settings_preserve_custom_and_save_explicitly() {let mut m=menu();enter(&mut m,4);assert!(m.view().rows[2].label.contains("47"));press(&mut m,Input::Activate);assert!(m.view().rows[0].label.contains("PlayStation"));enter(&mut m,1);assert!(m.view().rows[1].label.contains("L3"));assert!(m.pending().is_none());let op=operation(enter(&mut m,4));match op.command {Command::SaveSettings{original,updated}=>{assert_eq!(original.version,"v1");assert_eq!(updated.labels,LabelStyle::PlayStation);assert_eq!(updated.max_seconds,47);},other=>panic!("{other:?}")};let mut m=menu();enter(&mut m,4);press(&mut m,Input::Activate);enter(&mut m,5);enter(&mut m,4);assert!(m.view().rows[0].label.contains("Both"));}
#[test] fn logs_refresh_and_controls_scroll() {let mut m=menu();let r=read(enter(&mut m,5));assert_eq!(r.kind,ReadKind::Logs);assert!(m.receive(Response::Read{id:r.id,result:Ok(ReadData::Logs(vec!["one".into(),"two".into(),"three".into()]))}));press(&mut m,Input::Down);assert_eq!(m.view().scroll,1);let r=read(press(&mut m,Input::Activate));assert_eq!(r.kind,ReadKind::Logs);press(&mut m,Input::Back);enter(&mut m,6);press(&mut m,Input::Down);assert_eq!(m.view().scroll,1);assert!(m.view().details.join(" ").contains("R3"));}
#[test] fn global_slot_retains_unknown_and_never_retries() {let mut m=menu();enter(&mut m,2);let op=operation(press(&mut m,Input::Activate));let mut slot=OperationSlot::default();assert!(slot.reserve(op.clone()));assert!(!slot.reserve(op.clone()));assert!(slot.complete(op.id,Outcome::Unknown("timed out".into())));assert_eq!(slot.state(),Some(&OperationState::Unknown("timed out".into())));assert!(!slot.reserve(op.clone()));press(&mut m,Input::Menu);assert!(!m.is_open());assert!(slot.reconcile(op.id,Outcome::Success("created".into())));assert_eq!(slot.state(),Some(&OperationState::Finished(Outcome::Success("created".into()))));assert!(!slot.reserve(op));}
#[test] fn mutation_result_requires_exact_id_and_unknown_stays_blocked() {let mut m=menu();enter(&mut m,2);let op=operation(press(&mut m,Input::Activate));assert!(!m.receive(Response::Mutation{id:RequestId{session:8,serial:op.id.serial},outcome:Outcome::Success("wrong".into())}));assert!(m.receive(Response::Mutation{id:op.id,outcome:Outcome::Unknown("timeout".into())}));assert!(m.view().status.contains("Outcome unknown"));assert!(press(&mut m,Input::Activate).is_empty());}
